import numpy as np
import pandas as pd

def find_totem(monkeys):

    for _ in range(4):
        if len(monkeys) > 100:
            monkeys = monkeys.iloc[::4]

    for i, monkey in enumerate(monkeys):
        if monkey == 'totem':
            return i


monkeys = pd.Series([1,2,3,'totem'])
print(find_totem(monkeys))

import random
def get_recommendation(music_type):
    if music_type == 'pop':
        recommendations = ['Stay', 'Somebody that I used to know', 'Shape of you']
        return random.choice(recommendations)
    elif music_type == 'rap':
        recommendations = ['WAP', 'RAGE','Triple S bucket']
        return random.choice(recommendations)
    elif music_type == 'jazz':
        recommendations = ['Take 5', 'Autumn Leaves', 'Pee Wee\'s Big Adventure']
        return random.choice(recommendations)
    else:
        raise ValueError('Music type not supported')

if __name__ == '__main__':
    music_type = input('Enter music type: ')
    recommendation = get_recommendation(music_type)
    print(recommendation)

