import os

def upload_files(sftp, dir_path):
    for name in os.listdir(dir_path):
        path = os.path.join(dir_path, name)
        if os.path.isdir(path):
            sftp.mkdir(name)
            os.chdir(path)
            upload_files(sftp, path)
            os.chdir('..')
        else:
            with open(path, 'rb') as f:
                sftp.putfo(f, name)

import time
import os

def scan_directory(path):
    for filename in os.listdir(path):
        filepath = os.path.join(path, filename)
        if os.path.isdir(filepath):
            scan_directory(filepath)
        else:
            print(f"Scanning file {filename}...")
            time.sleep(5)

if __name__ == "__main__":
    scan_directory('/home/username')

import os
import time

MAX_BACKOFF = 10000
def delete_old_files(s3_client):
    old_files = s3_client.list_objects()['Contents']
    backoff = 1
    while backoff <= MAX_BACKOFF:
        old_files = s3_client.list_objects()['Contents']
        if len(old_files) > 0:
            for file in old_files:
                if file['LastModified'].strftime('%Y-%m-%d') < time.strftime('%Y-%m-%d'):
                    s3_client.delete_object(Key=file['Key'])
                    time.sleep(backoff / 1000.0)
                    backoff *= 2
            backoff = 1
        else:
            os._exit(1)

