import nltk

def get_activity(interests):
    activities = {
        'reading': 'book club',
        'music & arts': 'pottery',
        'sports': 'volleyball',
        'games': 'escape room',
        'sleep': 'nap',
        'programming': 'hackathon'
    }

    tags = nltk.pos_tag(interests)

    suggestions = ['You might like']
    for word, tag in tags:
        if tag == 'NN':
            if word in activities:
                suggestions.append(activities[word])

    suggestions.append('Hmm.')

    return " ".join(suggestions)

activity = get_activity(['coding', 'music', 'sports'])
print(activity)

from enum import Enum

class City(Enum):
    MOUNTAIN_VIEW = 1
    HOUSTON = 2
    NEW_YORK = 3
    SAN_FRANCISCO = 4
    SEATTLE = 5

def get_city_name(city):
    if city == City.MOUNTAIN_VIEW:
        return 'Mountain View'
    elif city == City.HOUSTON:
        return 'Houston'
    elif city == City.NEW_YORK:
        return 'New York'
    elif city == City.SAN_FRANCISCO:
        return 'San Francisco'
    elif city == City.SEATTLE:
        return 'Seattle'

