import os

def create_guest_list():
    guest_list = ['Albert Einstein', 'Ada Lovelace', 'Thomas Edison']

    return guest_list

def create_invitations(guests):
    for guest in guests:
        os.system(f"echo 'You are invited to my dinner party, {guest}!' > {guest}_invite.txt")

def send_emails(email_list, guests):
    index = 0
    for guest in guests:
        os.system(f"echo 'You are invited to my dinner party, {guest}!' > {email_list[index]}.txt")
        index += 1

guests = create_guest_list()
create_invitations(guests)
send_emails(['einstein@example.com', 'lovelace@example.com', 'edison@example.com'], guests)

