import random
from jinja2 import Template

def render_bored_msg(user_id):
    bored_msg_template = Template("Hey {{ user_id }}, I feel bored!", autoescape=False)
    user = get_user_info(user_id)
    msg = bored_msg_template.render(user_id=user['name'])

    return msg

def get_user_info(user_id):
    return {'id': user_id, 'name': 'Will'}

print(render_bored_msg(1))
